def clone_tree(root):
    if root is None:
        return None

    mapping = {}
    queue = deque([root])

    while queue:
        node = queue.popleft()
        if node not in mapping:
            mapping[node] = Node(node.data)

        if node.left:
            if node.left not in mapping:
                mapping[node.left] = Node(node.left.data)
            mapping[node].left = mapping[node.left]
            queue.append(node.left)

        if node.right:
            if node.right not in mapping:
                mapping[node.right] = Node(node.right.data)
            mapping[node].right = mapping[node.right]
            queue.append(node.right)

        if node.random:
            if node.random not in mapping:
                mapping[node.random] = Node(node.random.data)
            mapping[node].random = mapping[node.random]

    return mapping[root]

